css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; }
.loader .bowl { position: absolute; left: 24%; top: 6%; width: 52%; height: 48%; border-radius: 8% 8% 46% 46% / 6% 6% 62% 62%; overflow: hidden; background: color-mix(in srgb, var(--accent-2) 18%, transparent); box-shadow: inset 0 0 0 2px color-mix(in srgb, var(--accent-2) 45%, transparent); animation: wine-tip calc(var(--loader-speed) * 2) ease-in-out infinite; }
.loader .wine { position: absolute; left: -20%; right: -20%; bottom: -10%; height: 66%; border-radius: 44% 44% 0 0 / 30% 30% 0 0; background: linear-gradient(var(--accent), color-mix(in srgb, #000 22%, var(--accent))); animation: wine-slosh calc(var(--loader-speed) * 2) ease-in-out infinite; }
.loader .stem { position: absolute; left: 47%; top: 54%; width: 6%; height: 30%; background: color-mix(in srgb, var(--accent-2) 45%, transparent); }
.loader .foot { position: absolute; left: 28%; right: 28%; bottom: 8%; height: 8%; border-radius: 50%; background: color-mix(in srgb, var(--accent-2) 45%, transparent); }
@keyframes wine-tip { 0%, 100% { transform: rotate(-8deg); } 50% { transform: rotate(8deg); } }
@keyframes wine-slosh { 0%, 100% { transform: rotate(9deg) translateX(-4%); } 50% { transform: rotate(-9deg) translateX(4%); } }
